// =============================================================================
// EZER — the lock screen's dove mark
//
// The owner's pick from the Blender variants (path A, Cinzel, Oct 2026): a
// rendered dove swoops under the wordmark and lands on the top right of the R
// while EZER fades in. Both are images so they line up with the approved
// render exactly: a white Cinzel wordmark tinted per theme, and a sprite
// sheet of the flight (scale and fade-in baked into each cell). Frame data and
// the PNGs are generated by E:\ezer-dove\work\export_app.py. Rerun it after a
// re-render rather than nudging numbers here.
// =============================================================================

import React, { useEffect, useState } from 'react';
import { Image, View } from 'react-native';
import Animated, {
  cancelAnimation,
  Easing,
  useAnimatedStyle,
  useReducedMotion,
  useSharedValue,
  withRepeat,
  withTiming,
} from 'react-native-reanimated';
import { useTheme } from '../utils/ThemeContext';
import { CELL, PERCH, WORD, XY } from './doveFrames';
import { HOVER } from './doveHoverFrames';

const SHEET = require('../assets/dove/dove-sheet.png');
const PERCHED = require('../assets/dove/dove-perch.png');
const WORDMARK = require('../assets/dove/wordmark-cinzel.png');
const HOVER_SHEET = require('../assets/dove/dove-hover.webp');
const LAST = XY.length - 1;

// On cream the white dove washes out, so light mode rings it with a faint
// brand-gold edge: the dove's own silhouette tinted and drawn at 8 small
// offsets behind it. Offsets are in dp, so the edge is the same at any size.
const EDGE = [[1, 0], [-1, 0], [0, 1], [0, -1], [0.7, 0.7], [-0.7, 0.7], [0.7, -0.7], [-0.7, -0.7]] as const;
const EDGE_DP = 0.9;
const EDGE_OPACITY = 0.6;

/** The dove's edge colour for the current theme, or null for none. */
function useEdge(): string | null {
  const { mode, colors } = useTheme();
  return mode === 'light' ? colors.gold : null;
}

function Perched({ k, onLoad }: { k: number; onLoad?: () => void }) {
  const edge = useEdge();
  const box = { position: 'absolute' as const, left: PERCH.x * k, top: PERCH.y * k, width: PERCH.w * k, height: PERCH.h * k };
  return (
    <>
      {edge &&
        EDGE.map(([dx, dy], i) => (
          <Image
            key={i}
            source={PERCHED}
            style={[box, { tintColor: edge, opacity: EDGE_OPACITY, transform: [{ translateX: dx * EDGE_DP }, { translateY: dy * EDGE_DP }] }]}
          />
        ))}
      <Image source={PERCHED} style={box} onLoad={onLoad} />
    </>
  );
}

/** The wordmark with the dove on the R. `width` is the wordmark's width in dp;
 *  the dove sits above that box (0.36 of the width), outside its layout. */
export function DoveMark({ width, perched = true, onLoad }: { width: number; perched?: boolean; onLoad?: () => void }) {
  const { colors } = useTheme();
  const k = width / WORD.w;
  return (
    <View style={{ width, height: WORD.h * k }} accessible accessibilityRole="image" accessibilityLabel="EZER">
      <Image source={WORDMARK} style={{ width, height: WORD.h * k, tintColor: colors.ink }} onLoad={onLoad} />
      {perched && <Perched k={k} />}
    </View>
  );
}

/** Space Grotesk's capital height as a share of the font size (measured on
 *  the k62: 'Wallet' at 26 spans 36px at 2x). */
const CAP = 0.69;

/** The mark width at which the dove's top to the word's baseline is exactly as
 *  tall as a capital of a `fontSize` title: the owner wants the bird's top on
 *  the title's roof and EZER's floor on its floor. */
export const markWidthForTitle = (fontSize: number) => Math.round((fontSize * CAP * WORD.w) / (WORD.h - PERCH.y));

/** The tab headers' mark. Only the word takes layout space (the dove overhangs
 *  into the padding), so a row with `alignItems: 'baseline'` puts EZER's floor
 *  on the title's baseline: Yoga reads this box's baseline as the word image's
 *  bottom. `roomAbove` keeps the dove's height for a mark that starts the
 *  screen, so the dove clears the status bar. */
export function HeaderDoveMark({ width = 56, roomAbove = false }: { width?: number; roomAbove?: boolean }) {
  return (
    <View style={roomAbove ? { paddingTop: Math.ceil((-PERCH.y * width) / WORD.w) } : null}>
      <DoveMark width={width} />
    </View>
  );
}

/**
 * The flight. Plays once over `duration` ms when `play` turns true, ending on
 * the same pose DoveMark draws, so swapping to DoveMark afterwards doesn't
 * move the dove. Hidden until then; `onLoad` reports the sprite sheet decoded,
 * so the caller can hold the start until there is something to see.
 * The wordmark's own opacity is the caller's (LockGate's existing fade).
 */
export function DoveFlight({
  width,
  duration,
  play,
  onLoad,
}: {
  width: number;
  duration: number;
  play: boolean;
  onLoad?: () => void;
}) {
  const reduced = useReducedMotion();
  const edge = useEdge();
  const k = width / WORD.w;
  const f = useSharedValue(0);
  useEffect(() => {
    if (play) f.value = withTiming(LAST, { duration, easing: Easing.linear });
  }, [f, duration, play]);

  // The cell window moves along the path; the sheet slides inside it.
  const box = useAnimatedStyle(() => {
    const i = Math.min(LAST, Math.round(f.value));
    return { transform: [{ translateX: XY[i][0] * k }, { translateY: XY[i][1] * k }] };
  });
  const sheet = useAnimatedStyle(() => {
    const i = Math.min(LAST, Math.round(f.value));
    return { transform: [{ translateX: -(i % CELL.cols) * CELL.w * k }, { translateY: -Math.floor(i / CELL.cols) * CELL.h * k }] };
  });

  // Reduced motion: no travel, the dove is simply there.
  if (reduced) {
    return <Perched k={k} onLoad={onLoad} />;
  }
  const size = { width: CELL.w * CELL.cols * k, height: CELL.h * CELL.rows * k };
  // Cells carry a 2px transparent margin, so the edge copies stay inside them.
  return (
    <Animated.View
      pointerEvents="none"
      style={[{ position: 'absolute', left: 0, top: 0, width: CELL.w * k, height: CELL.h * k, overflow: 'hidden', opacity: play ? 1 : 0 }, box]}
    >
      {edge &&
        EDGE.map(([dx, dy], i) => (
          <Animated.View key={i} style={{ position: 'absolute', left: dx * EDGE_DP, top: dy * EDGE_DP, opacity: EDGE_OPACITY }}>
            <Animated.Image source={SHEET} style={[size, { tintColor: edge }, sheet]} />
          </Animated.View>
        ))}
      <Animated.Image source={SHEET} style={[size, sheet]} onLoad={onLoad} />
    </Animated.View>
  );
}

/**
 * The wait after the passcode: the dove lifts off the R and flaps in place
 * above it (the "hover" loader render, E:\ezer-dove\work\export_hover.py),
 * instead of the still perched mark. Loops while mounted; LockGate mounts it
 * only for that phase. The perched dove shows until the sheet has decoded, so
 * the R is never bare.
 */
export function DoveHover({ width }: { width: number }) {
  const reduced = useReducedMotion();
  const edge = useEdge();
  const k = width / WORD.w;
  const [loaded, setLoaded] = useState(false);
  const f = useSharedValue(0);
  useEffect(() => {
    if (reduced || !loaded) return;
    f.value = withRepeat(withTiming(HOVER.n, { duration: (HOVER.n / HOVER.fps) * 1000, easing: Easing.linear }), -1);
    return () => cancelAnimation(f);
  }, [f, reduced, loaded]);
  const sheet = useAnimatedStyle(() => {
    const i = Math.floor(f.value) % HOVER.n;
    return { transform: [{ translateX: -(i % HOVER.cols) * HOVER.w * k }, { translateY: -Math.floor(i / HOVER.cols) * HOVER.h * k }] };
  });

  if (reduced) return <Perched k={k} />;
  const size = { width: HOVER.w * HOVER.cols * k, height: HOVER.h * HOVER.rows * k };
  return (
    <>
      {!loaded && <Perched k={k} />}
      <View
        pointerEvents="none"
        style={{ position: 'absolute', left: HOVER.x * k, top: HOVER.y * k, width: HOVER.w * k, height: HOVER.h * k, overflow: 'hidden', opacity: loaded ? 1 : 0 }}
      >
        {edge &&
          EDGE.map(([dx, dy], i) => (
            <View key={i} style={{ position: 'absolute', left: dx * EDGE_DP, top: dy * EDGE_DP, opacity: EDGE_OPACITY }}>
              <Animated.Image source={HOVER_SHEET} style={[size, { tintColor: edge }, sheet]} />
            </View>
          ))}
        <Animated.Image source={HOVER_SHEET} style={[size, sheet]} onLoad={() => setLoaded(true)} />
      </View>
    </>
  );
}
